package app.xenet.client;
import android.app.Activity;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.hardware.Camera;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Local-only QR scanner. Camera frames are never saved or transmitted. */
@SuppressWarnings("deprecation") public final class ScanActivity extends Activity implements SurfaceHolder.Callback {
 private SurfaceView preview;private Camera camera;private boolean ready,resumed;private final ExecutorService decoder=Executors.newSingleThreadExecutor();private final AtomicBoolean decoding=new AtomicBoolean();private final Handler main=new Handler(Looper.getMainLooper());
 private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+.5f);}
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setBackgroundColor(0xff101215);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(20),0,dp(12),0);TextView title=new TextView(this);title.setText(R.string.scanner_title);title.setTextColor(-1);title.setTextSize(20);title.setIncludeFontPadding(false);title.setGravity(Gravity.CENTER_VERTICAL);title.setTypeface(android.graphics.Typeface.createFromAsset(getAssets(),"fonts/Manrope-650.ttf"));header.addView(title,new LinearLayout.LayoutParams(0,-2,1));ImageButton close=new ImageButton(this);close.setImageResource(R.drawable.ic_close);close.setColorFilter(-1);close.setScaleType(ImageView.ScaleType.CENTER_INSIDE);close.setPadding(dp(12),dp(12),dp(12),dp(12));close.setBackgroundColor(android.graphics.Color.TRANSPARENT);close.setContentDescription("Close scanner");close.setOnClickListener(v->finish());header.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));box.addView(header,new LinearLayout.LayoutParams(-1,dp(64)));preview=new SurfaceView(this);box.addView(preview,new LinearLayout.LayoutParams(-1,0,1));setContentView(box);preview.getHolder().addCallback(this);if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},1);}
 public void surfaceCreated(SurfaceHolder h){ready=true;open();}public void surfaceChanged(SurfaceHolder h,int f,int w,int z){}public void surfaceDestroyed(SurfaceHolder h){ready=false;close();}protected void onResume(){super.onResume();resumed=true;open();}protected void onPause(){resumed=false;close();super.onPause();}protected void onDestroy(){decoder.shutdownNow();super.onDestroy();}public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==1&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)open();else finish();}
 private void open(){if(!ready||!resumed||camera!=null||(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED))return;try{camera=Camera.open();Camera.Parameters p=camera.getParameters();List<Camera.Size> sizes=p.getSupportedPreviewSizes();Camera.Size best=sizes.get(0);for(Camera.Size s:sizes)if(Math.abs(s.width* s.height-640*480)<Math.abs(best.width*best.height-640*480))best=s;p.setPreviewSize(best.width,best.height);if(p.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);camera.setParameters(p);Camera.CameraInfo info=new Camera.CameraInfo();Camera.getCameraInfo(0,info);int rotation=getWindowManager().getDefaultDisplay().getRotation()*90;camera.setDisplayOrientation((info.orientation-rotation+360)%360);camera.setPreviewDisplay(preview.getHolder());camera.setPreviewCallback((bytes,c)->{if(!decoding.compareAndSet(false,true))return;Camera.Size s=c.getParameters().getPreviewSize();byte[] frame=bytes.clone();try{decoder.execute(()->{try{PlanarYUVLuminanceSource source=new PlanarYUVLuminanceSource(frame,s.width,s.height,0,0,s.width,s.height,false);Map<DecodeHintType,Object> hints=new EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.POSSIBLE_FORMATS,Collections.singletonList(BarcodeFormat.QR_CODE));Result result=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(source)),hints);main.post(()->{if(!isFinishing()){setResult(RESULT_OK,new Intent().putExtra("text",result.getText()));finish();}});}catch(Exception ignored){}finally{decoding.set(false);}});}catch(RejectedExecutionException ignored){decoding.set(false);}});camera.startPreview();}catch(Exception e){close();setResult(RESULT_CANCELED,new Intent().putExtra("cameraError",true));finish();}}
 private void close(){if(camera!=null){try{camera.setPreviewCallback(null);camera.stopPreview();camera.release();}catch(Exception ignored){}camera=null;}}
}
